const dimensionHunterSheet=new Image();dimensionHunterSheet.assetSrc='assets/dimension-hunter-v2.png';
function dimensionHunterSample(a,point){return {x:point.x,y:point.y,valid:dist(a.origin,point)<=450&&lineClear(a.origin,point),link:false};}
function beginDimensionHunter(e){e.state='attack';e.elapsed=0;e.struck=false;let a={pattern:'dimensionTrail',bespoke:true,windup:2.2,fired:false,origin:{x:e.x,y:e.y},previous:{x:p.x,y:p.y},samples:[]};a.samples.push(dimensionHunterSample(a,p));e.attack=a;}
const dimensionHunterAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r11e5')return dimensionHunterAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='dimensionTrail'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=350&&clear){beginDimensionHunter(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,100*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed+=dt;
 let continuous=dist(a.previous,p)<=220&&lineClear(a.previous,p);
 while(a.samples.length<13&&e.elapsed+1e-8>=a.samples.length*.1){let at=a.samples.length*.1,t=Math.max(0,Math.min(1,(at-before)/(e.elapsed-before||1))),point=continuous?{x:a.previous.x+(p.x-a.previous.x)*t,y:a.previous.y+(p.y-a.previous.y)*t}:{x:p.x,y:p.y},sample=dimensionHunterSample(a,point),prev=a.samples[a.samples.length-1];sample.link=continuous&&sample.valid&&prev.valid&&dist(prev,sample)<=220&&lineClear(prev,sample);a.samples.push(sample);}a.previous={x:p.x,y:p.y};
 if(!a.fired&&e.elapsed+1e-8>=2.2){a.fired=true;e.struck=true;if(dimensionHunterContact(a,p))hurt(84);playSound('impact',e.x,e.y);}
 if(e.elapsed+1e-8>=3.2){e.attack=null;e.state='idle';e.t=3;}

};
const dimensionHunterDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r11e5'||!dimensionHunterSheet.complete||!dimensionHunterSheet.naturalWidth||!dimensionHunterSheet.naturalHeight)return dimensionHunterDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='dimensionTrail')f={row:2,col:e.elapsed<1.2?0:e.elapsed<2.2?1:e.elapsed<2.5?2:3};let q=project(e.x,e.y),sw=dimensionHunterSheet.naturalWidth/4,sh=dimensionHunterSheet.naturalHeight/3,w=285,h=w*sh/sw,anchor=[[.8,.8,.8,.8],[.72,.72,.71,.72],[.67,.69,.67,.68]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,dimensionHunterSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(dimensionHunterSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const dimensionHunterSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r11e5'?175:dimensionHunterSizeBase(e);
function dimensionHunterNearest(from,to,point){let dx=to.x-from.x,dy=to.y-from.y,l=dx*dx+dy*dy,t=l?Math.max(0,Math.min(1,((point.x-from.x)*dx+(point.y-from.y)*dy)/l)):0;return {x:from.x+dx*t,y:from.y+dy*t};}
function dimensionHunterEdges(a){let edges=[];for(let i=0;i<a.samples.length;i++){let q=a.samples[i];if(!q.valid||!lineClear(a.origin,q))continue;let prev=a.samples[i-1];edges.push([q,q]);if(q.link&&prev?.valid&&lineClear(a.origin,prev)&&lineClear(prev,q))edges.push([prev,q]);}return edges;}
function dimensionHunterContact(a,point){return dimensionHunterEdges(a).some(([from,to])=>{let q=dimensionHunterNearest(from,to,point);return dist(q,point)<=18&&lineClear(q,point);});}
const dimensionHunterGroundBase=drawGroundEffects;drawGroundEffects=()=>{dimensionHunterGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r11e5'):enemies)){let a=e.attack;if(e.species!=='r11e5'||e.hp<=0||a?.pattern!=='dimensionTrail'||e.elapsed>=2.55)continue;let q=project(a.origin.x,a.origin.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.lineCap='round';ctx.fillStyle=a.fired?'#baffff99':'#45e3e544';ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=36;for(let [from,to]of dimensionHunterEdges(a)){if(!visibleAt(from.x,from.y)&&!visibleAt(to.x,to.y))continue;if(from===to){ctx.beginPath();ctx.arc(from.x-a.origin.x,from.y-a.origin.y,18,0,Math.PI*2);ctx.fill();}else{ctx.beginPath();ctx.moveTo(from.x-a.origin.x,from.y-a.origin.y);ctx.lineTo(to.x-a.origin.x,to.y-a.origin.y);ctx.stroke();}}ctx.lineWidth=2;ctx.strokeStyle=a.fired?'#ffffff':e.elapsed<1.2?'#6bffff':'#ffe09c';for(let [from,to]of dimensionHunterEdges(a)){ctx.beginPath();ctx.moveTo(from.x-a.origin.x,from.y-a.origin.y);ctx.lineTo(to.x-a.origin.x,to.y-a.origin.y);ctx.stroke();}ctx.restore();}};

if(typeof registerDirectEnemy==='function')registerDirectEnemy('r11e5',animateEnemy,drawRegionEnemy);
